#!/usr/bin/env bash
# Bundle item 208_mil_summaries_1124 (thread "Site: Build Military committee archive", 24 Nov 2569, asked by the 3x-daily routine;
# item number reserved by the routine). SELF-CONTAINED: payload embedded at the end as base64 tar.gz.
# Military 2569, surgical data-only update (no design change). Senate documents, all Rpublic=1:
#  - Main committee 29 (Thu 5 Nov 2569): summary ref 11244987 + minutes (บันทึกการประชุม) ref 11244974 -> agenda card becomes a summary.
#  - Main committee 30 (Thu 12 Nov): summary ref 11244991 -> upcoming card becomes a summary.
#  - Main committee 31 (Thu 19 Nov): summary ref 11244997 -> upcoming card becomes a summary.
#  - Military-affairs subcommittee 32 (Wed 18 Nov): summary (press release) ref 11244915 -> agenda card becomes a summary.
#  Easy-read wording; complaints written as allegations; NO petitioner, foundation, contact details, staff or signatory names.
# index.html + meetings.json: meetings 29-31 swapped (live "media" kept), EZ.cal, SHARE_V, TL, UPDATED, SUBS (military).
# sub-military.html + .json: meeting 32 swapped (live "media" kept), EZ.cal, SHARE, TL, UPDATED.
# i18n-en.json: ADD-ONLY English lines. Share pages s/29.html s/30.html s/31.html s/military-32.html + cards/QR.
# Then meeting_pages.py (m/NN.html). Idempotent; no git, no network. Needs $HUB ($BUILD optional).
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
S=208_mil_summaries_1124
M="$HUB/military/2569"
for f in index.html meetings.json i18n-en.json sub-military.html sub-military.json; do
  test -f "$M/$f" || { echo "$S: $M/$f missing" >&2; exit 1; }; done
PAY=$(mktemp -d); trap 'rm -rf "$PAY"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xzf - -C "$PAY"
test -f "$PAY/payload.json" || { echo "$S: embedded payload missing" >&2; exit 1; }
(cd "$PAY/files" && find . -type f) | while read -r f; do
  mkdir -p "$(dirname "$M/$f")"; cmp -s "$PAY/files/$f" "$M/$f" || cp -f "$PAY/files/$f" "$M/$f"; done
python3 - "$M" "$PAY/payload.json" <<'PY'
import json, os, re, sys
M, PAYF = sys.argv[1], sys.argv[2]
P = json.load(open(PAYF, encoding='utf-8'))
dec = json.JSONDecoder(); changed = []; DAY = '2026-11-24'
ser = lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')
def put(p, t):
    if open(p, encoding='utf-8').read() != t:
        open(p, 'w', encoding='utf-8').write(t); changed.append(os.path.relpath(p, M))
def one(lines, pre):
    idx = [i for i, l in enumerate(lines) if l.startswith(pre)]
    assert len(idx) == 1, f'{pre} not found once'; return idx[0]
def jline(lines, pre, dump):
    i = one(lines, pre); body = lines[i][len(pre):]; val, end = dec.raw_decode(body); tail = body[end:]
    assert pre + dump(val) + tail == lines[i], f'{pre} does not round-trip; not touching it'
    return i, val, tail
def updated(lines):
    k = one(lines, 'const UPDATED="'); cur = lines[k][15:25]
    if cur < DAY: lines[k] = lines[k].replace(cur, DAY, 1)
def swap(arr, new):
    by = {(m['n'], m['date']): k for k, m in enumerate(arr)}
    for m in new.values():
        m = dict(m); key = (m['n'], m['date'])
        if key in by:
            old = arr[by[key]]
            if 'media' in old: m['media'] = old['media']       # media belongs to the video items
            else: m.pop('media', None)
            arr[by[key]] = m
        else:
            arr.append(m)
    arr.sort(key=lambda m: (m['date'], m['n']), reverse=True); return arr
for page, d in P['pages'].items():
    p = os.path.join(M, page); lines = open(p, encoding='utf-8').read().split('\n')
    i, arr, tail = jline(lines, 'const DATA=', ser); lines[i] = 'const DATA=' + ser(swap(arr, d['meetings'])) + tail
    lines[one(lines, 'const TL=')] = d['TL']
    updated(lines)
    # SHARE_P line: set only these meetings' share tokens + QR entries (older meetings keep their live tokens)
    k = one(lines, 'const SHARE_P=')
    def share(l):
        m = re.fullmatch(r'const SHARE_P=("[^"]*"),SHARE_V=(\{[^}]*\}),SHARE_QR=(\[[^\]]*\]);', l)
        assert m, 'SHARE_P line shape changed; not touching it'
        return m.group(1), json.loads(m.group(2)), json.loads(m.group(3))
    pre, v, q = share(lines[k]); bpre, bv, bq = share(d['SHARE'])
    assert pre == bpre and lines[k] == f'const SHARE_P={pre},SHARE_V={json.dumps(v)},SHARE_QR={json.dumps(q)};', 'SHARE_P does not round-trip'
    for n in d['meetings']:
        v[n] = bv[n]
        if int(n) in bq and int(n) not in q: q.append(int(n))
    v = dict(sorted(v.items(), key=lambda kv: int(kv[0]), reverse=True)); q.sort(reverse=True)
    lines[k] = f'const SHARE_P={pre},SHARE_V={json.dumps(v)},SHARE_QR={json.dumps(q)};'
    i, ez, tail = jline(lines, 'const EZ=', lambda a: json.dumps(a, ensure_ascii=False))
    ez['cal'] = d['cal']; lines[i] = 'const EZ=' + json.dumps(ez, ensure_ascii=False) + tail
    if page == 'index.html':
        i, subs, tail = jline(lines, 'const SUBS=', ser)
        for x in subs:
            if x['key'] in P['subs']: x.update(P['subs'][x['key']])
        lines[i] = 'const SUBS=' + ser(subs) + tail
    put(p, '\n'.join(lines))
    jp = os.path.join(M, d['json']); raw = open(jp, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f"{d['json']} does not round-trip"
    put(jp, json.dumps(swap(ms, d['jmeetings']), ensure_ascii=False, indent=1))
ip = os.path.join(M, 'i18n-en.json'); raw = open(ip, encoding='utf-8').read(); d = json.loads(raw)
assert json.dumps(d, ensure_ascii=False, separators=(',', ':')) == raw, 'i18n-en.json format changed; not touching it'
for k, v in P['en'].items(): d.setdefault(k, v)              # add-only
put(ip, json.dumps(d, ensure_ascii=False, separators=(',', ':')))
print('208_mil_summaries_1124: changed', len(changed), 'files:', ', '.join(changed) or 'none (already applied)')
PY
MP="$BUILD/meeting_pages.py"; test -s "$MP" || MP="$PAY/meeting_pages.py"
python3 "$MP" "$M" >/dev/null
python3 - "$M" <<'PY'
import json, re, sys
M = sys.argv[1]; dec = json.JSONDecoder()
def data(page):
    for l in open(f'{M}/{page}', encoding='utf-8').read().split('\n'):
        if l.startswith('const DATA='): return {m['n']: m for m in dec.raw_decode(l[11:])[0]}
a = data('index.html'); s = data('sub-military.html')
js = {m['n']: m for m in json.load(open(f'{M}/meetings.json', encoding='utf-8'))}
sj = {m['n']: m for m in json.load(open(f'{M}/sub-military.json', encoding='utf-8'))}
for src, n, d, refs in ((a, 29, '2026-11-05', ('11244987', '11244974')), (a, 30, '2026-11-12', ('11244991',)),
                        (a, 31, '2026-11-19', ('11244997',)), (s, 32, '2026-11-18', ('11244915',)),
                        (js, 29, '2026-11-05', ('11244987', '11244974')), (js, 31, '2026-11-19', ('11244997',)), (sj, 32, '2026-11-18', ('11244915',))):
    m = src[n]
    assert m['date'] == d and not m.get('agenda_only') and not m.get('upcoming'), f'meeting {n}: still agenda/upcoming'
    for r in refs: assert any('ref=' + r in x.get('url', '') for x in m['docs']), f'meeting {n}: doc {r} missing'
assert a[29]['chair'] == 'นายวิรัตน์ รักษ์พันธ์', 'main 29 presiding chair'
assert [x['k'] for x in a[31]['docs']][:2] == ['notice', 'doc'], 'main 31 agenda doc lost'
assert any(v['kind'] == 'pre' for v in a[31]['media'].get('videos', [])), 'main 31 pre video lost'
assert a[32].get('upcoming') or a[32]['date'] == '2026-11-24', 'main 32 untouched'
for m in (a[29], a[30], a[31], s[32]):
    t = json.dumps(m, ensure_ascii=False)
    for bad in ('@', '0 2831', '9178', '๙๑๗๘', 'โทรศัพท์', 'บุษยพรรณ', 'สนั่น', 'กัณหาชาติ', 'ปูลัง', 'ปุลัง', 'กำปง', 'สุรางคณา', 'วิษณุ', 'รัชนีกร', 'สอบสวน ', '140 ปี'):
        assert bad not in t, f'blocked text {bad!r} in meeting {m["n"]}'
for f in ('s/29.html', 's/30.html', 's/31.html', 's/military-32.html', 'm/29.html', 'm/30.html', 'm/31.html'):
    t = open(f'{M}/{f}', encoding='utf-8').read()
    for bad in ('@senate', '0 2831', '9178', 'บุษยพรรณ', 'สนั่น', 'ปุลัง', 'ปูลัง'):
        assert bad not in t, f'blocked text {bad!r} in {f}'
assert 'ref=11244987' in open(f'{M}/m/29.html', encoding='utf-8').read(), 'meeting page m/29 not refreshed'
en = json.load(open(f'{M}/i18n-en.json', encoding='utf-8'))
def norm(s):   # same key rule as archive/i18n/i18n.py norm()
    s = re.sub(r"[๐-๙]", lambda m: str("๐๑๒๓๔๕๖๗๘๙".index(m.group(0))), s); s = re.sub(r"\s+", " ", s).strip(); n = []
    return re.sub(r"\d+(?:[.,:]\d+)*", lambda m: (n.append(1), "{%d}" % (len(n) - 1))[1], s)
for m in (a[29], a[30], a[31], s[32]):
    for k in [m['headline'], m['summary']] + [x for it in m['items'] for x in it[:2]]:
        assert norm(k) in en, 'English line missing: ' + k[:40]
for page in ('index.html', 'sub-military.html'):
    t = open(f'{M}/{page}', encoding='utf-8').read()
    assert 'id="vidkind-js"' in t and 'id="novdl-css"' in t and 'id="friction-js"' in t, f'{page}: live layer missing'
print('208_mil_summaries_1124 OK')
PY
exit 0
